(function(root){'use strict';
const fields=Object.freeze({kcal:['能量','kcal'],protein:['蛋白质','g'],carb:['碳水化合物','g'],fat:['脂肪','g'],fiber:['膳食纤维','g'],sugars:['总糖','g'],addedSugars:['添加糖','g'],saturatedFat:['饱和脂肪','g'],sodium:['钠','mg'],salt:['盐','g'],calcium:['钙','mg'],iron:['铁','mg'],potassium:['钾','mg'],magnesium:['镁','mg'],zinc:['锌','mg'],phosphorus:['磷','mg'],selenium:['硒','µg'],iodine:['碘','µg'],vitaminA_RAE:['维生素A RAE','µg'],vitaminD:['维生素D','µg'],vitaminE:['维生素E','mg'],vitaminK:['维生素K','µg'],vitaminB1:['维生素B1','mg'],vitaminB2:['维生素B2','mg'],vitaminB6:['维生素B6','mg'],vitaminB12:['维生素B12','µg'],folate_DFE:['叶酸 DFE','µg'],vitaminC:['维生素C','mg']});
function number(v){if(v==null||typeof v==='string'&&!v.trim())return null;if(typeof v!=='number'&&typeof v!=='string')throw Error('数值格式无效');const n=Number(v);if(!Number.isFinite(n)||n<0||n>100000)throw Error('营养值必须是有效非负数');return n;}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;}
function record(input,id){if(!input.confirmedSynthetic)throw Error('当前只支持合成演示账号；请勿保存真实健康信息');const name=String(input.name||'').trim().slice(0,100);if(!name)throw Error('请填写食物名称');if(!validDate(input.date))throw Error('请选择有效摄入日期');if(!['breakfast','lunch','dinner','snack'].includes(input.slot))throw Error('请选择餐次');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(input.time))throw Error('请选择有效时间');const nutrients={};const row={id,date:input.date,time:input.time,slot:input.slot,name,grams:number(input.grams),schemaVersion:2,source:'user-demo-entry',synthetic:true,note:'人工确认的合成示例；未进行图像营养识别',origin:['camera','gallery','manual'].includes(input.origin)?input.origin:'manual',photo:null,sticker:{status:'text-only',photoPersisted:false},analysis:{status:'not-connected',provider:null}};for(const [k,[,unit]]of Object.entries(fields)){const value=number(input[k]);row[k]=value;nutrients[k]={value,unit,basis:'consumed',status:value===null?'unknown':'known',source:{kind:'user-entry',verified:false}};}row.nutrients=nutrients;return row;}
function summary(rows){return Object.fromEntries(Object.keys(fields).map(k=>{const vals=rows.map(r=>r.nutrients&&Object.prototype.hasOwnProperty.call(r.nutrients,k)?(r.nutrients[k]?.unit===fields[k][1]&&r.nutrients[k]?.basis==='consumed'?r.nutrients[k].value:null):r[k]).filter(v=>typeof v==='number'&&Number.isFinite(v)&&v>=0);return[k,{value:vals.length?vals.reduce((a,b)=>a+b,0):null,known:vals.length,total:rows.length}];}));}
function scale(value,grams){return value==null||grams==null?null:number(value)*number(grams)/100;}
root.NutriFoodCaptureContract={fields,number,validDate,record,summary,scale};if(typeof module!=='undefined')module.exports=root.NutriFoodCaptureContract;
})(typeof window!=='undefined'?window:globalThis);
